params.command:
$ErrorActionPreference='Stop'
$src='C:\Users\Xxkan\mhw-safe-branch-delete2'
$wt='C:\Users\Xxkan\branchzero-pr127'
if(Test-Path $wt){ git -C $src worktree remove --force $wt 2>$null; if(Test-Path $wt){ Remove-Item -Recurse -Force $wt } }
git -C $src fetch origin --prune
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }
git -C $src worktree add --detach $wt origin/main
if($LASTEXITCODE -ne 0){ throw 'worktree add failed' }
git -C $wt checkout -b reconcile/branchzero-pr127
git -C $wt merge --no-ff --no-commit origin/agent/bridge-priority-scheduler-20260929
$mergeExit=$LASTEXITCODE
$conflicts=@(git -C $wt diff --name-only --diff-filter=U)
if($mergeExit -ne 0 -and $conflicts.Count -gt 0){
  Write-Output ('CONFLICTS='+($conflicts -join ','))
  git -C $wt merge --abort
  exit 20
}
python -m py_compile "$wt\heaven-bridge\worker.py"
if($LASTEXITCODE -ne 0){ git -C $wt merge --abort 2>$null; exit 21 }
python "$wt\heaven-bridge\test_worker.py"
if($LASTEXITCODE -ne 0){ git -C $wt merge --abort 2>$null; exit 22 }
python "$wt\heaven-bridge\tests\test_worker.py"
if($LASTEXITCODE -ne 0){ git -C $wt merge --abort 2>$null; exit 23 }
git -C $wt diff --check
if($LASTEXITCODE -ne 0){ git -C $wt merge --abort 2>$null; exit 24 }
git -C $wt commit -m "Merge branch 'agent/bridge-priority-scheduler-20260929' into main"
if($LASTEXITCODE -ne 0){ exit 25 }
git -C $wt fetch origin main
$remote=(git -C $wt rev-parse origin/main).Trim()
$parent=(git -C $wt rev-parse HEAD^1).Trim()
if($remote -ne $parent){ Write-Output "MAIN_MOVED remote=$remote parent=$parent"; exit 26 }
git -C $wt push origin HEAD:main
if($LASTEXITCODE -ne 0){ exit 27 }
git -C $wt fetch origin main
$head=(git -C $wt rev-parse HEAD).Trim(); $verified=(git -C $wt rev-parse origin/main).Trim()
if($head -ne $verified){ throw "push verification mismatch $head $verified" }
git -C $wt push origin --delete agent/bridge-priority-scheduler-20260929
[pscustomobject]@{merged=$true;main_sha=$verified;source_deleted=($LASTEXITCODE -eq 0);tests=@('py_compile','heaven-bridge/test_worker.py','heaven-bridge/tests/test_worker.py','git diff --check')} | ConvertTo-Json -Depth 4
